const suttaCache = new Map();

function cloneData(data) {
  return typeof structuredClone === "function"
    ? structuredClone(data)
    : JSON.parse(JSON.stringify(data));
}

async function loadCatalog() {
  return {
    ...cloneData(EMBEDDED_CATALOG),
    suttas: [...EMBEDDED_CATALOG.suttas].sort((a, b) => a.order - b.order)
  };
}

async function loadSutta(id) {
  if (suttaCache.has(id)) {
    return suttaCache.get(id);
  }

  const sutta = EMBEDDED_SUTTAS[id];
  if (!sutta) {
    throw new Error("経典データを読み込めませんでした");
  }

  const copy = cloneData(sutta);
  suttaCache.set(id, copy);
  return copy;
}

const REVIEW_INTERVALS = {
  1: 1,
  2: 3,
  3: 7,
  4: 14,
  5: 30
};

function applyReviewResult(sectionProgress = {}, result, today = todayKey()) {
  const currentBox = Number(sectionProgress.box || 0);
  let box = currentBox;

  if (result === "good") {
    box = Math.min(currentBox + 1, 5);
  } else if (result === "bad") {
    box = 1;
  }

  const interval = result === "unsure"
    ? REVIEW_INTERVALS[box] || 1
    : REVIEW_INTERVALS[box] || 1;

  return {
    ...sectionProgress,
    box,
    nextReview: addDays(today, interval),
    lastResult: result,
    lastReviewed: today
  };
}

function isDue(sectionProgress, today = todayKey()) {
  return Boolean(
    sectionProgress &&
    sectionProgress.nextReview &&
    sectionProgress.nextReview <= today
  );
}

function todayKey(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function addDays(dateKey, days) {
  const [year, month, day] = dateKey.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  date.setDate(date.getDate() + days);
  return todayKey(date);
}

const STORAGE_KEY = "psma:v1";
const EXPORT_SCHEMA = "pali-sutta-memorization-app";

const defaultState = {
  version: 1,
  settings: {
    fontSize: "M",
    theme: "auto",
    showKana: true,
    showJa: true,
    recognitionLang: "si-LK",
    repeatTarget: 10
  },
  progress: {},
  activity: {}
};

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return structuredClone(defaultState);
    }

    return mergeState(JSON.parse(raw));
  } catch {
    return structuredClone(defaultState);
  }
}

function saveState(state) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function createExportData() {
  return {
    schema: EXPORT_SCHEMA,
    exportedAt: new Date().toISOString(),
    state: loadState()
  };
}

function importState(data) {
  const state = normalizeImportedState(data);
  saveState(state);
  applySettings(state.settings);
  window.dispatchEvent(new CustomEvent("psma:progress-changed"));
  return state;
}

function updateSettings(patch) {
  const state = loadState();
  state.settings = { ...state.settings, ...patch };
  saveState(state);
  applySettings(state.settings);
  return state.settings;
}

function applySettings(settings) {
  document.documentElement.dataset.fontSize = settings.fontSize;
  document.documentElement.dataset.theme = settings.theme;
}

function getSuttaProgress(suttaId) {
  const state = loadState();
  return state.progress[suttaId] || { repCount: 0, sections: {} };
}

function incrementRepCount(suttaId) {
  const state = loadState();
  const current = state.progress[suttaId] || { repCount: 0, sections: {} };
  current.repCount = (current.repCount || 0) + 1;
  current.lastStudied = todayKey();
  state.progress[suttaId] = current;
  saveState(state);
  return current.repCount;
}

function resetRepCount(suttaId) {
  const state = loadState();
  const current = state.progress[suttaId] || { repCount: 0, sections: {} };
  current.repCount = 0;
  current.lastStudied = todayKey();
  state.progress[suttaId] = current;
  saveState(state);
  return current.repCount;
}

function updateSectionReview(suttaId, sectionId, result) {
  const state = loadState();
  const current = state.progress[suttaId] || { repCount: 0, sections: {} };
  const currentSection = current.sections?.[sectionId] || {};
  current.sections = {
    ...(current.sections || {}),
    [sectionId]: applyReviewResult(currentSection, result)
  };
  current.lastStudied = todayKey();
  state.progress[suttaId] = current;
  state.activity = recordDailyActivity(state.activity);
  saveState(state);
  window.dispatchEvent(new CustomEvent("psma:progress-changed"));
  return current.sections[sectionId];
}

// 日次の学習実績 (日付キー → その日の評価回数)。古い記録は自動で間引く。
function recordDailyActivity(activity = {}, today = todayKey()) {
  const next = { ...activity };
  next[today] = (Number(next[today]) || 0) + 1;
  const keys = Object.keys(next).sort();
  const MAX_DAYS = 550;
  if (keys.length > MAX_DAYS) {
    keys.slice(0, keys.length - MAX_DAYS).forEach((key) => {
      delete next[key];
    });
  }
  return next;
}

function getActivityStats() {
  const state = loadState();
  const activity = state.activity || {};
  const today = todayKey();
  const todayCount = Number(activity[today]) || 0;

  let streak = 0;
  let cursor = todayCount > 0 ? today : addDays(today, -1);
  while (Number(activity[cursor]) > 0) {
    streak += 1;
    cursor = addDays(cursor, -1);
  }

  const totalDays = Object.values(activity).filter((count) => Number(count) > 0).length;
  return { todayCount, streak, totalDays, activity };
}

function getCompletion(summary) {
  const progress = getSuttaProgress(summary.id);
  const sections = Object.values(progress.sections || {});
  const learned = sections.filter((section) => section.box >= 3).length;
  const masteredSections = sections.filter((section) => section.box >= 5).length;
  // バーは box 合計ベース (2026-07-19 実機フィードバック): 1回の評価でも進捗が動く。
  // 「暗記済みN/M節」の数字は従来どおり box3 以上の節数。
  const boxSum = sections.reduce((sum, section) => sum + Math.min(5, Math.max(0, Number(section.box) || 0)), 0);
  const total = summary.sectionCount || 0;
  return {
    learned,
    total,
    ratio: total > 0 ? boxSum / (total * 5) : 0,
    // 完全暗唱: 全節が box 5 (最上位) に到達
    mastered: total > 0 && masteredSections >= total
  };
}

function getLearningStats(catalog) {
  const state = loadState();
  const today = todayKey();
  const tomorrow = addDays(today, 1);
  const weekEnd = addDays(today, 7);
  const totalSections = catalog.suttas.reduce((sum, sutta) => sum + (sutta.sectionCount || 0), 0);
  let learnedSections = 0;
  let scheduledSections = 0;
  let dueToday = 0;
  let dueTomorrow = 0;
  let dueThisWeek = 0;
  let totalReps = 0;
  let lastStudied = "";

  catalog.suttas.forEach((sutta) => {
    const progress = state.progress[sutta.id] || {};
    totalReps += Number(progress.repCount || 0);
    if (progress.lastStudied && progress.lastStudied > lastStudied) {
      lastStudied = progress.lastStudied;
    }

    Object.values(progress.sections || {}).forEach((section) => {
      if (section.box >= 3) {
        learnedSections += 1;
      }
      if (section.nextReview) {
        scheduledSections += 1;
      }
      if (isDue(section, today)) {
        dueToday += 1;
      } else if (section.nextReview === tomorrow) {
        dueTomorrow += 1;
      }
      if (section.nextReview && section.nextReview > today && section.nextReview <= weekEnd) {
        dueThisWeek += 1;
      }
    });
  });

  return {
    totalSuttas: catalog.suttas.length,
    totalSections,
    learnedSections,
    scheduledSections,
    dueToday,
    dueTomorrow,
    dueThisWeek,
    totalReps,
    lastStudied,
    learnedRatio: totalSections > 0 ? learnedSections / totalSections : 0
  };
}

function countDueReviews(catalog) {
  return getDueReviewRefs(catalog).length;
}

function getDueReviewRefs(catalog) {
  const state = loadState();
  const today = todayKey();
  return catalog.suttas.flatMap((sutta) => {
    const sections = state.progress[sutta.id]?.sections || {};
    return Object.entries(sections)
      .filter(([, sectionProgress]) => isDue(sectionProgress, today))
      .map(([sectionId, sectionProgress]) => ({
        suttaId: sutta.id,
        suttaTitle: sutta.title,
        sectionId,
        nextReview: sectionProgress.nextReview,
        box: sectionProgress.box
      }));
  });
}

function getUpcomingReviewRefs(catalog, limit = 8) {
  const state = loadState();
  const today = todayKey();
  const refs = catalog.suttas.flatMap((sutta) => {
    const sections = state.progress[sutta.id]?.sections || {};
    return Object.entries(sections)
      .filter(([, sectionProgress]) => sectionProgress.nextReview && sectionProgress.nextReview > today)
      .map(([sectionId, sectionProgress]) => ({
        suttaId: sutta.id,
        suttaTitle: sutta.title,
        sectionId,
        nextReview: sectionProgress.nextReview,
        box: sectionProgress.box
      }));
  }).sort((a, b) =>
    a.nextReview.localeCompare(b.nextReview) ||
    a.suttaTitle.localeCompare(b.suttaTitle) ||
    a.sectionId.localeCompare(b.sectionId)
  );

  return refs.slice(0, limit);
}

function getReviewScheduleRefs(catalog, limit = 50) {
  const state = loadState();
  const refs = catalog.suttas.flatMap((sutta) => {
    const sections = state.progress[sutta.id]?.sections || {};
    return Object.entries(sections)
      .filter(([, sectionProgress]) => sectionProgress.nextReview)
      .map(([sectionId, sectionProgress]) => ({
        suttaId: sutta.id,
        suttaTitle: sutta.title,
        sectionId,
        nextReview: sectionProgress.nextReview,
        box: sectionProgress.box
      }));
  }).sort((a, b) =>
    a.nextReview.localeCompare(b.nextReview) ||
    a.suttaTitle.localeCompare(b.suttaTitle) ||
    a.sectionId.localeCompare(b.sectionId)
  );

  return refs.slice(0, limit);
}

function mergeState(parsed) {
  return {
    ...defaultState,
    ...parsed,
    settings: {
      ...defaultState.settings,
      ...(parsed.settings || {})
    },
    progress: parsed.progress || {},
    activity: parsed.activity || {}
  };
}

function normalizeImportedState(data) {
  const source = data?.schema === EXPORT_SCHEMA && data.state ? data.state : data;

  if (!isPlainObject(source)) {
    throw new Error("読み込めるデータ形式ではありません。");
  }

  return {
    ...defaultState,
    version: 1,
    settings: sanitizeSettings(source.settings),
    progress: sanitizeProgress(source.progress),
    activity: sanitizeActivity(source.activity)
  };
}

function sanitizeActivity(activity) {
  if (!isPlainObject(activity)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(activity)
      .filter(([key, value]) => /^\d{4}-\d{2}-\d{2}$/.test(key) && Number.isFinite(Number(value)) && Number(value) > 0)
      .map(([key, value]) => [key, Math.min(999, Math.round(Number(value)))])
  );
}

function sanitizeSettings(settings) {
  if (!isPlainObject(settings)) {
    return { ...defaultState.settings };
  }

  const fontSizes = new Set(["S", "M", "L", "XL"]);
  const themes = new Set(["auto", "light", "dark"]);
  const recognitionLangs = new Set(["ja-JP", "si-LK"]);
  const repeatTarget = Number(settings.repeatTarget);

  return {
    fontSize: fontSizes.has(settings.fontSize) ? settings.fontSize : defaultState.settings.fontSize,
    theme: themes.has(settings.theme) ? settings.theme : defaultState.settings.theme,
    showKana: typeof settings.showKana === "boolean" ? settings.showKana : defaultState.settings.showKana,
    showJa: typeof settings.showJa === "boolean" ? settings.showJa : defaultState.settings.showJa,
    recognitionLang: recognitionLangs.has(settings.recognitionLang) ? settings.recognitionLang : defaultState.settings.recognitionLang,
    repeatTarget: Number.isFinite(repeatTarget) ? Math.min(100, Math.max(1, Math.round(repeatTarget))) : defaultState.settings.repeatTarget
  };
}

function sanitizeProgress(progress) {
  if (!isPlainObject(progress)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(progress)
      .filter(([, value]) => isPlainObject(value))
      .map(([suttaId, value]) => [suttaId, sanitizeSuttaProgress(value)])
  );
}

function sanitizeSuttaProgress(progress) {
  const repCount = Number(progress.repCount);
  const result = {
    repCount: Number.isFinite(repCount) ? Math.max(0, Math.round(repCount)) : 0,
    sections: sanitizeSections(progress.sections)
  };

  if (typeof progress.lastStudied === "string") {
    result.lastStudied = progress.lastStudied;
  }

  return result;
}

function sanitizeSections(sections) {
  if (!isPlainObject(sections)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(sections)
      .filter(([, value]) => isPlainObject(value))
      .map(([sectionId, value]) => [sectionId, sanitizeSectionProgress(value)])
  );
}

function sanitizeSectionProgress(progress) {
  const box = Number(progress.box);
  const result = {
    box: Number.isFinite(box) ? Math.min(5, Math.max(0, Math.round(box))) : 0
  };

  ["nextReview", "lastResult", "lastReviewed"].forEach((key) => {
    if (typeof progress[key] === "string") {
      result[key] = progress[key];
    }
  });

  return result;
}

function isPlainObject(value) {
  return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

async function requestMicrophoneAccess(mediaDevices) {
  if (!mediaDevices || typeof mediaDevices.getUserMedia !== "function") {
    const error = new Error("Microphone access is not supported in this browser.");
    error.name = "NotSupportedError";
    throw error;
  }

  const stream = await mediaDevices.getUserMedia({ audio: true });
  try {
    return true;
  } finally {
    const tracks = typeof stream?.getTracks === "function" ? stream.getTracks() : [];
    tracks.forEach((track) => {
      try {
        track.stop();
      } catch {
        // The permission check is complete even if a browser already ended the track.
      }
    });
  }
}

function classifyMicrophoneAccessError(error) {
  const name = String(error?.name || "");
  if (["NotAllowedError", "PermissionDeniedError", "SecurityError"].includes(name)) {
    return "denied";
  }
  if (["NotFoundError", "DevicesNotFoundError"].includes(name)) {
    return "not-found";
  }
  if (["NotReadableError", "TrackStartError", "AbortError"].includes(name)) {
    return "unavailable";
  }
  if (name === "NotSupportedError") {
    return "unsupported";
  }
  return "unknown";
}

function renderHome(app, catalog) {
  const titleItems = catalog.suttas.length;
  const bodySections = catalog.suttas.reduce((sum, sutta) => sum + (sutta.bodySectionCount ?? Math.max(0, (sutta.sectionCount || 0) - 1)), 0);
  const list = document.createElement("section");
  list.className = "stack home-screen";
  list.innerHTML = `
    <section class="home-hero">
      <div class="hero-copy">
        <p class="hero-eyebrow">PALI / RECITE / REMEMBER</p>
        <h2>今日の読誦を、<br><em>静かに積み重ねる。</em></h2>
        <p class="hero-description">経典を声に出し、表示を少しずつ隠しながら、無理なく暗記を続けます。</p>
      </div>
      <div class="hero-orbit" aria-hidden="true">
        <img class="hero-icon" src="./icons/hero-bodhi.png?v=83" alt="">
      </div>
    </section>
    ${renderReviewCta(catalog)}
    ${renderPracticeCard()}
    <div class="section-heading">
      <div>
        <p class="label">LIBRARY / ${catalog.suttas.length} TEXTS</p>
        <h2>学習する経典</h2>
      </div>
      <span class="section-counter">読誦${catalog.suttas.length}経典 / 本文${bodySections}節＋経典名${titleItems}件</span>
    </div>
    <div class="sutta-list"></div>
  `;

  const suttaList = list.querySelector(".sutta-list");
  catalog.suttas.forEach((sutta) => {
    const completion = getCompletion(sutta);
    const item = document.createElement("a");
    item.className = "sutta-row";
    item.href = `#/sutta/${encodeURIComponent(sutta.id)}`;
    item.dataset.mastered = String(Boolean(completion.mastered));
    item.innerHTML = `
      <span class="sutta-order">${sutta.order}</span>
      <span class="sutta-main">
        <span class="sutta-title">${escapeHtml(sutta.title)}${completion.mastered ? '<i class="mastered-leaf" title="完全暗唱" aria-label="完全暗唱"></i>' : ""}</span>
        <span class="sutta-pali">${escapeHtml(sutta.titlePali || "")}</span>
      </span>
      <span class="progress-block" aria-label="定着度 ${Math.round(completion.ratio * 100)}パーセント">
        <span>定着度 ${Math.round(completion.ratio * 100)}%</span>
        <span class="progress-track"><span style="width: ${completion.ratio * 100}%"></span></span>
      </span>
    `;
    suttaList.append(item);
  });

  app.append(list);
}

function renderReviewCta(catalog) {
  const stats = getLearningStats(catalog);
  if (stats.scheduledSections === 0) {
    return "";
  }

  if (stats.dueToday > 0) {
    const dueRefs = getDueReviewRefs(catalog);
    const suttaCount = new Set(dueRefs.map((ref) => ref.suttaId)).size;
    return `
      <section class="review-cta" data-state="due" aria-label="今日の復習">
        <div class="review-cta-copy">
          <p class="label">TODAY / REVIEW</p>
          <h2>今日の復習 <strong>${stats.dueToday}</strong> 項目</h2>
          <p>${suttaCount}経典から順に出題します。</p>
        </div>
        <a class="button primary review-cta-start" href="#/review">はじめる</a>
      </section>
    `;
  }

  const upcoming = getUpcomingReviewRefs(catalog, 1)[0];
  const nextText = upcoming ? `次回は ${formatShortDate(upcoming.nextReview)}${stats.dueTomorrow > 0 ? `（${stats.dueTomorrow}項目）` : ""}` : "";
  return `
    <section class="review-cta" data-state="clear" aria-label="今日の復習">
      <div class="review-cta-copy">
        <p class="label">TODAY / REVIEW</p>
        <h2>今日の復習は完了しています</h2>
        <p>${nextText}</p>
      </div>
    </section>
  `;
}

function formatShortDate(dateKey) {
  const [, month, day] = String(dateKey || "").split("-").map(Number);
  return month && day ? `${month}月${day}日` : dateKey || "";
}

// 精進の記録: 連続日数と直近15週のヒートマップ (学習履歴が1日でもあれば表示)
function renderPracticeCard() {
  const stats = getActivityStats();
  if (stats.totalDays === 0) {
    return "";
  }

  const WEEKS = 15;
  const now = new Date();
  const mondayOffset = (now.getDay() + 6) % 7;
  const start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - mondayOffset - (WEEKS - 1) * 7);
  const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

  let weeks = "";
  for (let week = 0; week < WEEKS; week += 1) {
    let cells = "";
    for (let day = 0; day < 7; day += 1) {
      const date = new Date(start.getFullYear(), start.getMonth(), start.getDate() + week * 7 + day);
      const key = todayKey(date);
      const count = Number(stats.activity[key]) || 0;
      const isFuture = date.getTime() > todayTime;
      const level = isFuture ? "future" : count === 0 ? 0 : count <= 2 ? 1 : count <= 5 ? 2 : 3;
      cells += `<i data-level="${level}" title="${date.getMonth() + 1}/${date.getDate()}: ${count}回"></i>`;
    }
    weeks += `<span class="hm-week">${cells}</span>`;
  }

  const streakText = stats.streak > 0
    ? `連続 <strong>${stats.streak}</strong> 日`
    : "今日からまた積み重ね";

  return `
    <section class="practice-card" aria-label="精進の記録">
      <div class="practice-head">
        <div>
          <p class="label">PRACTICE / DAILY</p>
          <h2>精進の記録</h2>
        </div>
        <p class="practice-stats">${streakText} ・ 今日 ${stats.todayCount}回 ・ 累計 ${stats.totalDays}日</p>
      </div>
      <div class="hm-scroll">
        <div class="heatmap" role="img" aria-label="直近${WEEKS}週の学習記録">${weeks}</div>
      </div>
      <p class="hm-legend"><span>少</span><i data-level="1"></i><i data-level="2"></i><i data-level="3"></i><span>多</span></p>
    </section>
  `;
}

