function setupSettingsChoiceControls(section) {
  section.querySelectorAll("[data-setting-option]").forEach((button) => {
    button.addEventListener("click", () => {
      const key = button.dataset.settingOption;
      const value = button.dataset.value;
      const settings = updateSettings({ [key]: value });
      applyFormValues(section, settings);
      button.closest("details").open = false;
      showStatus(section, "保存しました。");
    });
  });
}

function setupDataTransferControls(section, form) {
  const exportButton = section.querySelector("[data-export]");
  const importButton = section.querySelector("[data-import]");
  const importFile = form.elements.importFile;

  exportButton.addEventListener("click", () => {
    const json = JSON.stringify(createExportData(), null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `pali-sutta-backup-${formatFileDate(new Date())}.json`;
    document.body.append(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 0);
    showStatus(section, "エクスポートしました。");
  });

  importButton.addEventListener("click", () => {
    importFile.click();
  });

  importFile.addEventListener("change", async () => {
    const file = importFile.files?.[0];
    if (!file) {
      return;
    }

    try {
      const parsed = JSON.parse(await file.text());
      const confirmed = confirm("現在の学習データを読み込んだファイルで上書きします。よろしいですか？");
      if (!confirmed) {
        showStatus(section, "インポートを中止しました。");
        return;
      }

      const imported = importState(parsed);
      applyFormValues(form, imported.settings);
      showStatus(section, "インポートしました。");
    } catch (error) {
      const message = error instanceof SyntaxError
        ? "JSONファイルを読み込めませんでした。"
        : error.message || "インポートできませんでした。";
      showStatus(section, message, "error");
    } finally {
      importFile.value = "";
    }
  });
}

function applyFormValues(section, settings) {
  const labels = {
    fontSize: {
      S: "小",
      M: "中",
      L: "大",
      XL: "特大"
    },
    theme: {
      auto: "端末に従う",
      light: "ライト",
      dark: "ダーク"
    },
    recognitionLang: {
      "si-LK": "シンハラ語",
      "ja-JP": "日本語"
    }
  };

  section.querySelectorAll("[data-setting-value]").forEach((target) => {
    const key = target.dataset.settingValue;
    target.textContent = labels[key]?.[settings[key]] || "";
  });

  section.querySelectorAll("[data-setting-option]").forEach((button) => {
    const isSelected = settings[button.dataset.settingOption] === button.dataset.value;
    button.setAttribute("aria-pressed", String(isSelected));
  });
}

function formatFileDate(date) {
  const pad = (value) => String(value).padStart(2, "0");
  return [
    date.getFullYear(),
    pad(date.getMonth() + 1),
    pad(date.getDate())
  ].join("") + "-" + [
    pad(date.getHours()),
    pad(date.getMinutes())
  ].join("");
}

function showStatus(section, message, tone = "") {
  const note = section.querySelector("#save-note");
  note.textContent = message;
  if (tone) {
    note.dataset.tone = tone;
  } else {
    delete note.dataset.tone;
  }
  window.clearTimeout(showStatus.timer);
  showStatus.timer = window.setTimeout(() => {
    note.textContent = "変更は自動保存されます。";
    delete note.dataset.tone;
  }, tone === "error" ? 2400 : 1200);
}

let activeGuideAudio = null;

async function renderSutta(app, catalog, suttaId, setTitle) {
  const summary = catalog.suttas.find((item) => item.id === suttaId);
  if (!summary) {
    renderMissing(app);
    setTitle("経典が見つかりません");
    return;
  }

  setTitle(summary.title);
  app.innerHTML = '<section class="loading">読み込み中...</section>';

  try {
    const sutta = await loadSutta(suttaId);
    renderReading(app, sutta);
  } catch (error) {
    app.innerHTML = `
      <section class="empty-state">
        <h2>読み込みに失敗しました</h2>
        <p>${error.message}</p>
        <a class="button primary" href="#/">ホームへ戻る</a>
      </section>
    `;
  }
}

